export interface Session {
  readonly lastActivityAt: number;
}

export const SESSION_TIMEOUT_MS = 30 * 60 * 1_000;

export function isSessionExpired(session: Session, now: number): boolean {
  return now - session.lastActivityAt >= SESSION_TIMEOUT_MS;
}

// Returns how many milliseconds remain before the session expires.
// If the session has already expired, returns 0.
export function remainingSessionMs(session: Session, now: number): number {
  const remaining = session.lastActivityAt + SESSION_TIMEOUT_MS - now;
  return remaining > 0 ? remaining : 0;
}

"use strict";

// Existing session utilities
// This module provides helpers around session validity including timeout logic.

const SESSION_TIMEOUT_MS = 30 * 60 * 1000; // 30 minutes

function isSessionExpired(lastActivityAt, now) {
  if (typeof lastActivityAt !== 'number' || typeof now !== 'number') {
    return true;
  }
  const elapsed = now - lastActivityAt;
  return elapsed >= SESSION_TIMEOUT_MS;
}

// Returns remaining milliseconds until session expires. If already expired, returns 0.
function remainingSessionMs(session, now) {
  // session is expected to have a lastActivityAt timestamp in milliseconds
  const lastActivityAt = session && typeof session.lastActivityAt === 'number' ? session.lastActivityAt : undefined;
  if (typeof now !== 'number') {
    // if now is not provided or invalid, use current time
    now = Date.now();
  }
  if (typeof lastActivityAt !== 'number') {
    return 0;
  }
  const elapsed = now - lastActivityAt;
  const remaining = SESSION_TIMEOUT_MS - elapsed;
  return remaining > 0 ? remaining : 0;
}

// Exported API (preserving existing exports)
module.exports = {
  isSessionExpired,
  remainingSessionMs,
};

